  return '#' + [ca.r + (cb.r - ca.r) * t, ca.g + (cb.g - ca.g) * t, ca.b + (cb.b - ca.b) * t].map(function (v) {
    return Math.round(clampRange(v, 0, 255)).toString(16).padStart(2, '0');
  }).join('');
