    var active = normalizeLyricTextureClarity(btn.getAttribute('data-lyric-texture-clarity')) === fx.lyricTextureClarity;
    btn.classList.toggle('active', active);
    btn.setAttribute('aria-pressed', active ? 'true' : 'false');
